#ifndef __MUMMYMAZE_GAMELEVELS_H__
#define __MUMMYMAZE_GAMELEVELS_H__

// The level data of Mummy Maze (which maze file and number each pyramid chamber plays, the maze pairs a classic game
// never picks, the world map's graph and the tutorial's five hard-coded mazes) is in the original's exe. port: no
// level data is in the repository (the user's rule on game data, 2026-11-03): LoadGameLevels() reads it at start-up
// from the player's own WinMM.exe, like the texts (GameText.h).
//
// - GameLevelsTable.inc (generated by games/mummymaze/tools/make_levels.py) lists each table's address in the 1.1
//   game image, its length and a hash: no data.
// - The tutorial's walls are not a table in the exe: 0x40f520 builds each part's maze in code. The loader reads
//   those statements' instructions (a load of a cell, an OR with a register that holds a wall bit, a store), after
//   checking the hash of the code.

#include <cstdint>
#include <vector>

namespace Sexy
{

extern int			kAdventureMaze[225];	// per pyramid and chamber (15 x 15): the maze file number
extern int			kAdventureLevel[225];	// per pyramid and chamber: the maze number in the file, minus 1
extern int			kExcluded[962];			// (file, maze) pairs a classic game never picks, after a leading word
extern int			kExcludedResume[966];	// (file, maze) pairs that LoadClassic skips when it picks the next chamber of a saved game
extern int			kMapPos[30];			// the world map: where each of the 15 pyramids is (x, y pairs)
extern int			kMapLinks[225];			// the world map: 15 x 15, 1 where a path joins two pyramids
extern int			kMapEdge[225];			// the world map: 15 x 15, the number of the path between two pyramids (negative: walked backwards)
extern int			kMapWay[252];			// the world map: six waypoints (x, y) per path, path numbers 1 to 19 (path n starts at pair 6n)
extern int			kTutorialMove[67];		// per tutorial step: the one move that is allowed (0 N, 1 W, 2 E, 3 S, 4 wait), 5 none, 6 and 7 the buttons
extern int			kRankScore[22];			// the points at which a classic game's rank rises

struct TutorialWall
{
	int		mCell;	// x * 10 + y
	int		mBits;	// the wall bits OR-ed into the cell
};

// The walls of tutorial part 0 to 4 (empty for another part, or when the exe did not match)
const std::vector<TutorialWall>&	TutorialWalls(int thePart);

// Reads the level data from the game folder's executable. Returns false when the executable is missing or a table
// does not match it (the tables are then zero; Mummy Maze Deluxe 1.1 is expected).
bool				LoadGameLevels();

}

#endif
